var longestBalanced = function (s) {
  const n = s.length;
  let ans = 0;
  for (let i = 0; i < n; ) {
    const start = i++;
    while (i < n && s[i] === s[i - 1]) 
        i++;
    ans = Math.max(ans, i - start);
  }

  ans = Math.max(ans, twoChars(s, 'a', 'b'));
  ans = Math.max(ans, twoChars(s, 'a', 'c'));
  ans = Math.max(ans, twoChars(s, 'b', 'c'));

  const pos = new Map();
  pos.set(key(0, 0), -1);

  let ca = 0, cb = 0, cc = 0;
