  first.fill(2147483647); 

  const touched = new Int32Array(2 * n + 1);
  let touchedSz = 0;

  let i = 0;
  while (i < n) {
    const segStart = i;

    first[n] = segStart - 1;
    touched[touchedSz++] = n;

    let d = 0;
    while (i < n && (s[i] === x || s[i] === y)) {
      d += (s[i] === x) ? 1 : -1;
      const idx = d + n;

